import React from 'react';
import { getArtifactUrl } from '@/lib/api';
import type { MonitorCheck } from '@pingwatch/shared';

interface CheckHistoryTableProps {
  checks: MonitorCheck[];
}

export function CheckHistoryTable({ checks }: CheckHistoryTableProps) {
  if (!checks || checks.length === 0) {
    return (
      <div className="text-center py-12 border border-[#30363D] rounded-lg bg-[#161B22]/50">
        <p className="text-sm text-[#8B949E]">No health checks recorded yet.</p>
        <p className="text-xs text-[#6E7681] mt-1">Checks are recorded automatically by the monitor worker.</p>
      </div>
    );
  }

  return (
    <div className="overflow-x-auto rounded-lg border border-[#30363D]">
      <table className="w-full text-left text-sm">
        <thead className="bg-[#161B22] border-b border-[#30363D] text-[11px] font-mono uppercase tracking-wider text-[#8B949E]">
          <tr>
            <th className="py-3 px-4">Status</th>
            <th className="py-3 px-4">Checked At</th>
            <th className="py-3 px-4">HTTP Status</th>
            <th className="py-3 px-4">Latency</th>
            <th className="py-3 px-4">Details</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-[#30363D] bg-[#0D1117]/80">
          {checks.map((check) => (
            <tr key={check.id} className="hover:bg-[#161B22]/50 transition-colors">
              <td className="py-3 px-4">
                <span
                  className={`inline-flex items-center gap-1.5 px-2 py-0.5 rounded text-xs font-mono font-medium ${
                    check.is_up
                      ? 'bg-[#00FF87]/10 text-[#00FF87]'
                      : 'bg-[#FF4D4F]/10 text-[#FF4D4F]'
                  }`}
                >
                  <span
                    className={`w-1.5 h-1.5 rounded-full ${
                      check.is_up ? 'bg-[#00FF87]' : 'bg-[#FF4D4F]'
                    }`}
                  />
                  {check.is_up ? 'UP' : 'DOWN'}
                </span>
              </td>
              <td className="py-3 px-4 text-xs font-mono text-[#E6EDF3]">
                {new Date(check.checked_at).toLocaleTimeString([], {
                  hour: '2-digit',
                  minute: '2-digit',
                  second: '2-digit',
                })}{' '}
                <span className="text-[#8B949E]">
                  {new Date(check.checked_at).toLocaleDateString()}
                </span>
              </td>
              <td className="py-3 px-4 font-mono text-xs">
                {check.status_code ? (
                  <span
                    className={
                      check.status_code >= 200 && check.status_code < 300
                        ? 'text-[#00FF87]'
                        : check.status_code >= 300 && check.status_code < 400
                        ? 'text-[#F0A500]'
                        : 'text-[#FF4D4F]'
                    }
                  >
                    {check.status_code}
                  </span>
                ) : (
                  <span className="text-[#8B949E]">—</span>
                )}
              </td>
              <td className="py-3 px-4 font-mono text-xs text-[#E6EDF3]">
                {check.response_ms !== null ? `${check.response_ms} ms` : '—'}
              </td>
              <td className="py-3 px-4 text-xs text-[#8B949E] max-w-xs truncate">
                {check.error_message ? (
                  <span className="text-[#FF7B72] font-mono" title={check.error_message}>
                    {check.error_message}
                  </span>
                ) : (
                  <span className="text-[#8B949E]">Normal response</span>
                )}
                {check.screenshot_path && (
                  <a
                    href={getArtifactUrl(check.screenshot_path) || '#'}
                    target="_blank"
                    rel="noreferrer"
                    className="block mt-1 text-[#58A6FF] hover:underline"
                  >
                    Open captured page
                  </a>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
